INSERT INTO public.topics (chapter_id,title,slug,description,source_page,display_order) SELECT c.id,x.title,x.slug,'Source-preserved and quality-gated reference material.',x.page::integer,x.ord::integer FROM (VALUES ('world-legislatures', 'আইনসভা সম্পর্কিত বিগত বছরের প্রশ্ন', 'legislature-past-exam-mcqs', '514', '3'),
