('famous-residences', 'বিখ্যাত সরকারি বাসভবন', 'official-residences-reference', '517', '1'),
('government-offices', 'সচিবালয় ও সরকারি কার্যালয়', 'secretariats-offices-reference', '518', '1')) x(chapter_slug,title,slug,page,ord) JOIN public.chapters c ON c.slug=x.chapter_slug AND c.book_id=(SELECT id FROM public.books WHERE title='Jubayer''s GK' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.chapter_id=c.id AND t.slug=x.slug);
