INSERT INTO public.source_pages (import_run_id,book_id,source_page,page_kind,raw_transcription,chapter_heading,topic_heading,confidence,extraction_method,model_name,notes,review_metadata) SELECT (SELECT id FROM public.import_runs WHERE pipeline_version='vision-quality-gated-batch-0514-0518-v1' ORDER BY started_at DESC LIMIT 1),b.id,517,'educational'::page_kind,'বিভিন্ন দেশের বিখ্যাত বাসভবন হোয়াইট হাউজ ♦ অবস্থান: ওয়াশিংটন ডিসি ♦ যুক্তরাষ্ট্রের প্রেসিডেন্টের সরকারি বাসভবন। এলিসি প্রাসাদ ♦ অবস্থান: প্যারিস ♦ ফ্রান্সের প্রেসিডেন্টের সরকারি বাসভবন। ৭, লোক কল্যাণ মার্গ ♦ অবস্থান: নয়াদিল্লি ♦ ভারতের প্রধানমন্ত্রীর সরকারি বাসভবন। রাষ্ট্রপতি ভবন ♦ অবস্থান: নয়াদিল্লি ♦ ভারতের রাষ্ট্রপতির সরকারি বাসভবন। মালকানাং প্রাসাদ ♦ অবস্থান: ম্যানিলা ♦ ফিলিপাইনের প্রেসিডেন্টের সরকারি বাসভবন। ১০নং ডাউনিং স্ট্রীট ♦ অবস্থান: লন্ডন ♦ ইংল্যান্ডের প্রধানমন্ত্রীর সরকারি বাসভবন। ১১নং ডাউনিং স্ট্রীট ♦ অবস্থান: লন্ডন ♦ ইংল্যান্ডের প্রধানমন্ত্রীর প্রাক্তন বাসভবন (বর্তমানে অর্থমন্ত্রীর বাসভবন)। মিরাফ্লোরেস ♦ অবস্থান: কারাকাস ♦ ভেনিজুয়েলার প্রেসিডেন্টের সরকারি বাসভবন। টেম্পল ট্রিস ♦ অবস্থান: কলম্বো ♦ শ্রীলংকার প্রধানমন্ত্রীর সরকারি বাসভবন। বাকিংহাম প্যালেস ♦ অবস্থান: লন্ডন ♦ ব্রিটেনের রাজার বাসভবন। মারদেকা প্রাসাদ ♦ অবস্থান: জাকার্তা ♦ ইন্দোনেশিয়ার প্রেসিডেন্টের সরকারি বাসভবন। বোগোর প্রাসাদ ♦ অবস্থান: জাকার্তা ♦ ইন্দোনেশিয়ার প্রেসিডেন্টের গ্রীষ্মকালীন বাসভবন। ব্লু হাউস ♦ অবস্থান: সিউল ♦ দক্ষিণ কোরিয়ার প্রেসিডেন্টের সরকারি বাসভবন। পোডালা প্রাসাদ ♦ অবস্থান: লাসা, তিব্বত ♦ তিব্বতের আধ্যাত্মিক প্রধান দালাইলামার বাসভবন। দি লজ ♦ অবস্থান: ক্যানবেরা ♦ অস্ট্রেলিয়ার প্রধানমন্ত্রীর সরকারি বাসভবন। Zubair''s GK - ৪৬০','বিভিন্ন দেশের বিখ্যাত বাসভবন','বিখ্যাত সরকারি বাসভবন','high'::confidence_level,'vision_ocr_with_image_grounded_review','gemini-3-flash-preview','Quality-gated extraction with ordered dense-image review and explicit verification status.','{"source_image_sha256":"7670c3d8695ce407c2057c5212830fba75cebdb66db3b30409465734abdd222c","extraction_model":"gemini-3-flash-preview","review_status":"accepted","corrections":[],"unresolved_spans":[],"accepted_content_tags":["topic_heading","table","fact","misc"],"physical_source_page":517,"printed_book_page":460,"artifact_reported_page":517,"visual_review_report":"/home/ubuntu/dontonyo/reports/batch-0514-0518_visual_review.md","external_verification_report":"/home/ubuntu/dontonyo/reports/batch-0514-0518_external_verification.md","page_number_mismatch":"Physical PDF page and visible printed footer are preserved separately."}'::jsonb FROM public.books b WHERE b.title='Jubayer''s GK' AND NOT EXISTS (SELECT 1 FROM public.source_pages s WHERE s.book_id=b.id AND s.source_page=517);
